   365→    let amount = 1000;
   366→    let btc = sui::balance::create_for_testing<BTC>(amount).into_coin(ctx);
   367→
   368→    let ctokens = reserve.mint_ctokens<MainMarket, BTC>(btc).into_coin(ctx);
   369→    assert!(ctokens.value() == amount);
   370→
   371→    assert!(reserve.util_rate() == float::from_quotient(0, 1));
   372→    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));
   373→
   374→    let btc = reserve.burn_ctokens<MainMarket, BTC>(ctokens);
   375→    assert!(btc.value() == amount);
